// pre: n &gt;= 0
// post: returns the factorial of n (n!)
int factorial(int n){
    if (n == 0){ // BASE CASE: The factorial of 0 is always 1.
        return 1;
    } else { // RECURSIVE CASE: We multiply 'n' by the factorial of the previous number.
        return n * factorial(n - 1);
    }
}

